class Solution {
public:
    int countConsistent(vector<int>& nums) {
        int n = nums.size();
        long long ans = 0;
        for (int left = 0; left < n; ++left) {
            int curMin = nums[left];
            int curAnd = nums[left];
            if (curMin == curAnd) ++ans;
            for (int right = left + 1; right < n; ++right) {
                curMin = min(curMin, nums[right]);
                curAnd &= nums[right];
                if (curMin == curAnd) ++ans;
            }
        }
        return (int)ans;
    }
};
